// Источник: web-тест .qa/e2e/tests/guided-prayer/gp-07-approved-source-line.spec.ts, план .qa/e2e/specs/guided-prayer.md (8.12), кейс .qa/tests/guided-prayer/GP-07-approved-source-line.md
// Тикет #a5decf4a · a5decf4a9de744b22c38c93f. Опора: S-17 экран молитвы и экран פרק תהילים — строка источника под текстом.
// Утверждения сделаны в админке 05–06.10 и необратимы. Только чтение.
// ערבית אשכנז и מנחה ספרד — всегда; סדר אזכרה, תהילים קי״ז/ל״ט, ברכות הגפן/העץ — по ключу, только с APP_SCHEME (без него эти шаги пропускаются).
import { expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabelStartsWith, tapText, expectVisibleText, pageCounter, swipeUp } from '../../helpers/ui.ts';
import { openPrayer, openRoute, hasDeepLinks, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const APPROVED_LINE = 'מקור: .+אושר על ידי .+\\d{1,2}\\.\\d{1,2}\\.\\d{4}.*';
const UNAPPROVED_LINE = 'הטקסט עדיין לא אושר.*';

/** Долистать до строки источника (утверждённой или нет). */
async function scrollToSourceLine(max = 10) {
  for (let i = 0; i <= max; i++) {
    if (await (await byTextMatches(APPROVED_LINE)).isDisplayed().catch(() => false)) return;
    if (await (await byTextMatches(UNAPPROVED_LINE)).isDisplayed().catch(() => false)) return;
    await swipeUp();
  }
}
async function expectApproved() {
  await scrollToSourceLine();
  await expect(byTextMatches(APPROVED_LINE)).toBeDisplayed();
  await expect(byTextMatches(UNAPPROVED_LINE)).not.toBeDisplayed();
}
/** Открыть ключ через deep link и встать на первый фрагмент (если есть счётчик). */
async function openKeyFirst(key: string) {
  await toHome();
  await openRoute(`/prayer/${key}`);
  const counter = await byTextMatches('\\d+ מתוך \\d+');
  const hasCounter = await counter.waitForDisplayed({ timeout: 10000 }).then(() => true, () => false);
  if (hasCounter) {
    const total = Number((await pageCounter()).split(' מתוך ')[1]);
    await goToPage(1, total);
  }
}

describe('Молитва по шагам', () => {
  afterEach(async () => { await toHome(); });

  it('GP-07 Утверждённые фрагменты: «מקור: … · אושר על ידי …»; неутверждённый — «הטקסט עדיין לא אושר…» #a5decf4a @prod-safe', async () => {
    // 1. ערבית אשכנז «3 מתוך 15» «המעריב ערבים» — утверждено.
    await openPrayer('arvit_ashkenaz', 'ערבית');
    expect(Number((await pageCounter()).split(' מתוך ')[1])).toBe(15);
    await goToPage(3, 15);
    expect(await pageCounter()).toBe('3 מתוך 15');
    await expectApproved();

    if (hasDeepLinks()) {
      // 2. סדר אזכרה אשכנז, фрагмент 1.
      await openKeyFirst('azkara_ashkenaz');
      await expectApproved();

      // 3. תהילים קי״ז и ל״ט.
      for (const [chapter, title] of [['117', 'תהילים קי״ז'], ['39', 'תהילים ל״ט']]) {
        await toHome();
        await openRoute(`/tehilim/${chapter}`);
        await (await byText(title)).waitForDisplayed({ timeout: 20000 });
        await expectApproved();
      }

      // 4. בורא פרי הגפן / העץ אשכנז.
      for (const key of ['beracha_hagefen_ashkenaz', 'beracha_haetz_ashkenaz']) {
        await openKeyFirst(key);
        await expectApproved();
      }
    }

    // 5. מנחה ספרד «1 מתוך 11» — не утверждено.
    await toHome();
    if (hasDeepLinks()) await openRoute('/prayer/mincha_sfarad');
    else {
      await openPrayer('mincha_ashkenaz', 'מנחה');
      await (await byLabelStartsWith('בחירת נוסח')).click();
      await tapText('ספרדי');
      const replace = await byText('החלף');
      if (await replace.isDisplayed().catch(() => false)) await replace.click();
    }
    await expectVisibleText('מנחה (ספרדי)');
    await goToPage(1, 11);
    await scrollToSourceLine();
    await expect(byTextMatches(UNAPPROVED_LINE)).toBeDisplayed();
    await expect(byTextContains('אושר על ידי')).not.toBeDisplayed();

    // Вернуть מנחה в נוסח профиля.
    if (!hasDeepLinks()) {
      await toHome();
      await openPrayer('mincha_ashkenaz', 'מנחה');
      if (await (await byText('מנחה (ספרדי)')).isDisplayed().catch(() => false)) {
        await (await byLabelStartsWith('בחירת נוסח')).click();
        await tapText('אשכנזי');
        const replace = await byText('החלף');
        if (await replace.isDisplayed().catch(() => false)) await replace.click();
      }
      await expectVisibleText('מנחה (אשכנזי)');
    }
  });
});
